Arguments: {"title":"Locate puzzle hole via pixel luminance","code":"const tabId = 2126149062;
const holeFinder = await browserjs(tabId, () => {
  const img = document.querySelector('.slider-img-bg-1konc');
  const canvas = document.createElement('canvas');
  canvas.width = img.naturalWidth;
  canvas.height = img.naturalHeight;
  const ctx = canvas.getContext('2d');
  ctx.drawImage(img, 0, 0);
  const data = ctx.getImageData(0, 0, canvas.width, canvas.height).data;

  // Let's find very dark areas or edges that form the puzzle piece hole
  // Let's sample luminance across x coordinates
  const colLuminance = [];
  for (let x = 0; x < canvas.width; x++) {
    let sum = 0;
    let count = 0;
    for (let y = 20; y < canvas.height - 20; y++) {
      const idx = (y * canvas.width + x) * 4;
      const r = data[idx];
      const g = data[idx+1];
      const b = data[idx+2];
      const lum = 0.299 * r + 0.587 * g + 0.114 * b;
      sum += lum;
      count++;
    }
    colLuminance.push(Math.round(sum / count));
  }
  return { width: canvas.width, height: canvas.height, colLuminance };
});

console.log("Image width:", holeFinder.width, "height:", holeFinder.height);
// Let's find local minima in luminance
const lums = holeFinder.colLuminance;
let minIdx = 0;
let minVal = 999;
// Ignore the borders (start from x = 60 to 280)
for (let x = 60; x < holeFinder.width - 40; x++) {
  if (lums[x] < minVal) {
    minVal = lums[x];
    minIdx = x;
  }
}
console.log("Min luminance at x =", minIdx, "val =", minVal);
console.log("Luminances around min:", lums.slice(Math.max(0, minIdx - 20), minIdx + 20));
